left, right = 0, len(h) - 1
left_max, right_max = h[left], h[right]
water = 0

while left < right:
    if left_max < right_max:
        left += 1
        if h[left] >= left_max:
            left_max = h[left]
        else:
            water += left_max - h[left]
    else:
        right -= 1
        if h[right] >= right_max:
            right_max = h[right]
        else:
            water += right_max - h[right]
